//! Standalone Verifier - Third-party independent reproducibility and attestation engine.

use crate::bundle::EvidenceBundle;
use crate::event::{EventKind, TraceEvent};
use crate::merkle::MerkleTree;
use crate::TraceError;
use serde::{Deserialize, Serialize};
use sha2::{Digest, Sha256};

/// Report generated by third-party independent verification.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct VerificationReport {
    pub bundle_id: String,
    pub target_name: String,
    pub tier: String,
    pub signature_valid: bool,
    pub merkle_root_valid: bool,
    pub total_events: usize,
    pub expected_merkle_root: String,
    pub expected_state_hash: String,
    pub replay_attempted: bool,
    pub replay_matched: Option<bool>,
    pub replayed_merkle_root: Option<String>,
    pub replayed_state_hash: Option<String>,
    pub summary: String,
}

/// Abstract interface for deterministic replay of target workloads without campaign state.
pub trait TargetReplayer {
    /// Replay execution given seed and fault schedule; returns (replayed_merkle_tree, final_state_hash).
    fn replay(
        &self,
        seed: u64,
        fault_schedule_json: &str,
    ) -> Result<(MerkleTree, String), TraceError>;
}

/// A reference seeded state-machine replayer used for algorithmic verification.
#[derive(Debug, Clone)]
pub struct DeterministicStateReplayer {
    pub step_count: u64,
}

impl DeterministicStateReplayer {
    pub fn new(step_count: u64) -> Self {
        Self { step_count }
    }
}

impl TargetReplayer for DeterministicStateReplayer {
    fn replay(
        &self,
        seed: u64,
        fault_schedule_json: &str,
    ) -> Result<(MerkleTree, String), TraceError> {
        let mut state = seed;
        let mut events = Vec::with_capacity(self.step_count as usize);

        for step in 0..self.step_count {
            // Deterministic LCG state transition conditioned on step, state, and fault schedule
            state = state
                .wrapping_mul(6364136223846793005)
                .wrapping_add(1442695040888963407);

            let event = TraceEvent::new(
                step,
                step * 1000,
                (step % 3) as u32,
                1,
                EventKind::InstructionStep,
                state.to_le_bytes().as_slice(),
                format!("State transition {step}: {state:016x}"),
            );
            events.push(event);
        }

        // Incorporate fault schedule into final state hash
        let mut final_hasher = Sha256::new();
        final_hasher.update(state.to_le_bytes());
        final_hasher.update(fault_schedule_json.as_bytes());
        let final_state_hash = crate::hex_encode(final_hasher.finalize());

        let leaf_hashes: Vec<[u8; 32]> = events.iter().map(|e| e.compute_leaf_hash()).collect();
        let tree = MerkleTree::from_hashed_leaves(leaf_hashes);

        Ok((tree, final_state_hash))
    }
}

/// Independent standalone verifier.
pub struct StandaloneVerifier;

impl StandaloneVerifier {
    /// Level 1: Static verification without execution (cryptographic signature and Merkle integrity).
    pub fn verify_static(bundle: &EvidenceBundle) -> Result<VerificationReport, TraceError> {
        let sig_res = bundle.verify_signature();
        let merkle_res = bundle.verify_merkle_integrity();

        let signature_valid = sig_res.is_ok();
        let merkle_root_valid = merkle_res.is_ok();

        if let Err(e) = sig_res {
            return Err(e);
        }
        if let Err(e) = merkle_res {
            return Err(e);
        }

        Ok(VerificationReport {
            bundle_id: bundle.bundle_id.clone(),
            target_name: bundle.target_name.clone(),
            tier: bundle.tier.clone(),
            signature_valid,
            merkle_root_valid,
            total_events: bundle.total_events,
            expected_merkle_root: bundle.merkle_root.clone(),
            expected_state_hash: bundle.final_state_hash.clone(),
            replay_attempted: false,
            replay_matched: None,
            replayed_merkle_root: None,
            replayed_state_hash: None,
            summary: "Static verification SUCCESSFUL: Valid Ed25519 signature and Merkle root integrity."
                .into(),
        })
    }

    /// Level 2: Dynamic verification with full execution replay (CLM-004).
    /// Asserts byte-exact trace hash & state hash match on third-party host without campaign access.
    pub fn verify_with_replay<R: TargetReplayer>(
        bundle: &EvidenceBundle,
        replayer: &R,
    ) -> Result<VerificationReport, TraceError> {
        let mut report = Self::verify_static(bundle)?;
        report.replay_attempted = true;

        let (replayed_tree, replayed_state_hash) =
            replayer.replay(bundle.seed, &bundle.fault_schedule_json)?;

        let replayed_root = replayed_tree.root_hex();
        report.replayed_merkle_root = Some(replayed_root.clone());
        report.replayed_state_hash = Some(replayed_state_hash.clone());

        if replayed_root != bundle.merkle_root {
            report.replay_matched = Some(false);
            report.summary = format!(
                "Replay DIVERGENCE: Merkle root mismatch! Expected {}, got {}",
                bundle.merkle_root, replayed_root
            );
            return Err(TraceError::ReplayDivergence {
                expected_merkle_root: bundle.merkle_root.clone(),
                actual_merkle_root: replayed_root,
            });
        }

        if !bundle.final_state_hash.is_empty() && replayed_state_hash != bundle.final_state_hash {
            report.replay_matched = Some(false);
            report.summary = format!(
                "Replay DIVERGENCE: State hash mismatch! Expected {}, got {}",
                bundle.final_state_hash, replayed_state_hash
            );
            return Err(TraceError::StateHashMismatch {
                expected: bundle.final_state_hash.clone(),
                actual: replayed_state_hash,
            });
        }

        report.replay_matched = Some(true);
        report.summary = "Full independent reproducibility VERIFIED: Bit-exact trace & state match across replay."
            .into();

        Ok(report)
    }
}
